import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"外掛","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/plugins.md","filePath":"zh-TW/user-guide/settings/plugins.md","lastUpdated":1787473456000}'),n={name:"zh-TW/user-guide/settings/plugins.md"};function s(l,e,d,i,c,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="外掛" tabindex="-1">外掛 <a class="header-anchor" href="#外掛" aria-label="Permalink to &quot;外掛&quot;">​</a></h1><p>列出所有已安裝的外掛，頁面頂部的徽章顯示目前載入的 Plugin SDK 版本——點擊它可以直接開啟<a href="./../../dev-guide/">開發手冊</a>，這個版本號正是為了對照手冊開發外掛而準備的。</p><p>頁面分成左右兩欄：左邊是已安裝的外掛，右邊是選取外掛的詳細資料。兩欄各自獨立捲動，外掛清單很長和設定表單很長互不牽扯。</p><p>如果沒有安裝任何外掛，頁面會顯示一個空狀態提示。</p><h2 id="外掛清單" tabindex="-1">外掛清單 <a class="header-anchor" href="#外掛清單" aria-label="Permalink to &quot;外掛清單&quot;">​</a></h2><p>每個已安裝的外掛佔一列，顯示名稱，下方是它的版本號。點擊某一列，右側就會開啟該外掛。</p><p>清單按「有什麼可操作的」排序：先是有自己設定項的外掛，其次是有元件可以關閉的，最後是其餘的；每一檔內部按名稱排列。</p><h2 id="選取的外掛" tabindex="-1">選取的外掛 <a class="header-anchor" href="#選取的外掛" aria-label="Permalink to &quot;選取的外掛&quot;">​</a></h2><p>右欄最上方是外掛的圖示、名稱和<strong>整體功能簡介</strong>。</p><p>再往下，如果外掛公開了自己的設定項(超出簡單啟用/停用的範疇)，會出現<strong>詳細資料</strong>和<strong>設定</strong>兩個索引標籤。沒有任何設定項的外掛不會顯示索引標籤列——整欄就是它的詳細資料。</p><h3 id="詳細資料" tabindex="-1">詳細資料 <a class="header-anchor" href="#詳細資料" aria-label="Permalink to &quot;詳細資料&quot;">​</a></h3><p>該外掛註冊的功能元件，按類型分組（搜尋來源、動態選單提供者等）。每個可切換的元件都有自己的<strong>啟用/停用核取方塊</strong>；標記為必要項目的元件會顯示一個鎖形圖示，不能關閉。把滑鼠停留在元件旁邊的 <strong>(!)</strong> 上，可以看到該元件的詳細功能說明。</p><p>當某個分組（或整個外掛）有 2 個及以上可切換元件時，標題旁會出現一個<strong>全選/全不選</strong>連結，點擊即可一次性切換該範圍內的所有核取方塊，不用逐個手動勾選。</p><h3 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h3><p>外掛自己的設定項，直接在這裡編輯，不再另外開啟對話方塊。如果外掛把設定分成了 2 組及以上，這裡還會有一列屬於它自己的索引標籤，每組一個。</p><p>按下<strong>確定</strong>之前，什麼都不會寫入。離開這個索引標籤——切回詳細資料，或者選擇另一個外掛——會把這些欄位回復到已儲存的值，這樣你放棄掉的修改就不會在之後被誤送出。</p><p>想看外掛設定實際長什麼樣、能改什麼(比如改一個觸發關鍵字)，可以參考<a href="./../instant-answers.html">即時答案與關鍵字功能</a>。</p><h2 id="flow-launcher-外掛生態支援" tabindex="-1">Flow Launcher 外掛生態支援 <a class="header-anchor" href="#flow-launcher-外掛生態支援" aria-label="Permalink to &quot;Flow Launcher 外掛生態支援&quot;">​</a></h2><p>除了基於 <code>Lertaro.PluginSdk</code> 構建的原生 C# 外掛之外，Lertaro 還透過內建的 Flow Launcher Bridge 提供了對龐大 Flow Launcher 社群外掛生態的原生級相容支援。</p><ul><li><strong>支援的外掛類型</strong>：相容 <strong>C# (.NET)</strong>、<strong>Python 3.12</strong>（支援根據 <code>requirements.txt</code> 自動在背景安裝 <code>pip</code> 相依套件）、<strong>Node.js v20 LTS</strong>（支援根據 <code>package.json</code> 自動在背景安裝 <code>npm</code> 相依套件）以及獨立<strong>可執行檔</strong>（<code>.exe</code>）編寫的 Flow Launcher 外掛。</li><li><strong>安裝方式</strong>：直接將第三方 Flow Launcher 外掛資料夾放入 <code>&lt;使用者資料目錄&gt;\\FlowData\\Plugins\\</code>，Lertaro 會自動辨識、載入並註冊其搜尋觸發詞與動作。</li><li><strong>純淨隔離執行環境</strong>：Python（<code>FlowData\\PythonEmbeded-{arch}</code>）與 Node.js（<code>FlowData\\NodeEmbeded-{arch}</code>）執行階段完全隔離在 Lertaro 的資料目錄中視需要自動下載部署，不依賴也不污染系統的全域環境變數與 PATH。</li><li><strong>設定與動作關鍵字</strong>：Flow 外掛的原生設定面板與觸發關鍵字已無縫接入 Lertaro 的設定介面中，享有相同的確定儲存與取消復原保護機制。</li></ul>',20)])])}const u=o(n,[["render",s]]);export{p as __pageData,u as default};
